-- 025: Completar la lección de los días de la semana (306).
-- Faltaban 木曜日 (jueves) y 金曜日 (viernes) → la semana estaba incompleta.
-- Ahora enseña los 7 días EN ORDEN (lunes→domingo) con la mnemotecnia de los
-- elementos (月 luna, 火 fuego, 水 agua, 木 árbol, 金 oro, 土 tierra, 日 sol).
-- Contenido verificado.

INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (306, 1, 'Los días de la semana', '曜日', 'Nombra los 7 días de la semana en orden.', 12, 10, 1, '{"activities":[{"id":"u1l10g0","kind":"intro_grammar","title":"曜日 — los días de la semana","pattern":"[elemento] + 曜日","explanation":"Cada día termina en 曜日 (ようび = «día de la semana»). Delante lleva un kanji de la naturaleza: 月 luna, 火 fuego, 水 agua, 木 árbol, 金 oro, 土 tierra, 日 sol. Por eso 月曜日 es lunes (día de la luna) y 日曜日 es domingo (día del sol).","example":{"jp":"今日は何曜日ですか。","reading":"きょうはなんようびですか","meaning":"¿Qué día es hoy?"}},{"id":"u1l10a1","kind":"intro_vocab","word":"月曜日","reading":"げつようび","meaning":"lunes","example":"月曜日から働きます。"},{"id":"u1l10a2","kind":"intro_vocab","word":"火曜日","reading":"かようび","meaning":"martes","example":"火曜日は忙しいです。"},{"id":"u1l10a3","kind":"intro_vocab","word":"水曜日","reading":"すいようび","meaning":"miércoles","example":"水曜日は休みです。"},{"id":"u1l10a4","kind":"intro_vocab","word":"木曜日","reading":"もくようび","meaning":"jueves","example":"木曜日に会いましょう。"},{"id":"u1l10a5","kind":"intro_vocab","word":"金曜日","reading":"きんようび","meaning":"viernes","example":"金曜日に映画を見ます。"},{"id":"u1l10a6","kind":"intro_vocab","word":"土曜日","reading":"どようび","meaning":"sábado","example":"土曜日は休みです。"},{"id":"u1l10a7","kind":"intro_vocab","word":"日曜日","reading":"にちようび","meaning":"domingo","example":"日曜日は家にいます。"},{"id":"u1l10q1","kind":"quiz","prompt":"¿Qué día es 木曜日?","options":["jueves","martes","sábado"],"correctIndex":0,"explanation":"木曜日 = もくようび = jueves (día del árbol 木)."},{"id":"u1l10q2","kind":"quiz","prompt":"¿Qué día es 金曜日?","options":["viernes","miércoles","lunes"],"correctIndex":0,"explanation":"金曜日 = きんようび = viernes (día del oro 金)."},{"id":"u1l10q3","kind":"quiz","prompt":"¿Cuál es el orden correcto de la semana?","options":["月・火・水・木・金・土・日","月・水・火・金・木・日・土","日・月・火・水・木・金・土"],"correctIndex":0,"explanation":"La semana va 月(lun) → 火 → 水 → 木 → 金 → 土(sáb) → 日(dom)."},{"id":"u1l10w1","kind":"write_sentence","prompt":"Escribe «jueves» en japonés.","hint":"木 + 曜日","accepted":["木曜日","もくようび"],"explanation":"木曜日 (もくようび) = jueves."},{"id":"u1l10sum","kind":"summary","learned":["月曜日 (lunes)","火曜日 (martes)","水曜日 (miércoles)","木曜日 (jueves)","金曜日 (viernes)","土曜日 (sábado)","日曜日 (domingo)"]}]}');
